import{_ as o,C as r,o as s,c as n,j as a,a as i,E as h,a2 as l}from"./chunks/framework.sc8Z_ZE3.js";const _=JSON.parse('{"title":"Seat takeover","description":"","frontmatter":{},"headers":[],"relativePath":"work/seat-takeover.md","filePath":"work/seat-takeover.md"}'),d={name:"work/seat-takeover.md"};function c(u,e,p,f,m,v){const t=r("Badge");return s(),n("div",null,[e[0]||(e[0]=a("h1",{id:"seat-takeover",tabindex:"-1"},[i("Seat takeover "),a("a",{class:"header-anchor",href:"#seat-takeover","aria-label":'Permalink to "Seat takeover"'},"​")],-1)),h(t,{type:"built",text:"Built"}),e[1]||(e[1]=l(' <a href="/docs/install/runners">Server runners</a> run only governed models, through the platform&#39;s gateway. A run phase that needs a person&#39;s own Claude or ChatGPT <strong>seat</strong> cannot run there, so it waits for that person to take it over on their own device.<h2 id="how-it-works" tabindex="-1">How it works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How it works&quot;">​</a></h2><ol><li>A run phase with the seat profile on the server runners pauses as <code>seat_required</code>.</li><li>The requester gets an attention item, and the run card offers the takeover on an <strong>online device that holds that engine&#39;s seat</strong> (Claude Code for a Claude seat, Codex for a ChatGPT seat).</li><li>The phase resumes there, from the platform&#39;s snapshot of the session.</li></ol><p>Without such a device, the pause says so by name: which engine and seat it waits for.</p><p>Devices report at their handshake which engines they run and whose seat they hold, so a takeover only goes to a device that can actually run it. A device of an older launcher reports no engine, and its turns are refused as <code>device_engine_missing</code>: update the launcher. See <a href="/docs/install/launcher">Launcher and devices</a>.</p><h2 id="limits" tabindex="-1">Limits <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;Limits&quot;">​</a></h2><ul><li>In the web app you cannot choose a pool target with the seat profile; that comes only from the API, a handoff or triage.</li></ul><p>See also <a href="/docs/work/session-pool">Session pool and handover</a>.</p>',12))])}const w=o(d,[["render",c]]);export{_ as __pageData,w as default};
